head.script:
         scwin.onpageload = function() {
			windowContainer1.createWindow({
				title : 'icon_left일때',
				src : 'windowContainer_MDI_TAB_icon_WESD-1044_(WSQ-5066)_sub0.xml',
				openAction : 'existWindow',
				userIconClass : "w2windowContainer_nameLayer_imageIcon1",
				userIconPosition : "left"
			});

			windowContainer1.createWindow({
				title : 'icon없을때',
				src : 'windowContainer_MDI_TAB_icon_WESD-1044_(WSQ-5066)_sub1.xml',
				openAction : 'existWindow',
			});

			windowContainer1.createWindow({
				title : 'icon_right일때',
				src : 'windowContainer_MDI_TAB_icon_WESD-1044_(WSQ-5066)_sub2.xml',
				openAction : 'existWindow',
				userIconClass : "w2windowContainer_nameLayer_imageIcon2",
				userIconPosition : "right"
			});

			windowContainer1.createWindow({
				title : 'iconPosition없을때',
				src : 'windowContainer_MDI_TAB_icon_WESD-1044_(WSQ-5066)_sub3.xml',
				openAction : 'existWindow',
				userIconClass : "w2windowContainer_nameLayer_imageIcon4",
			});
		};

		scwin.onpageunload = function() {

		};



	scwin.trigger1_onclick = function(e) {
		windowContainer1.createWindow({
			title : 'sub3',
			src : 'windowContainer_MDI_TAB_icon_WESD-1044_(WSQ-5066)_sub3.xml',
			openAction : 'existWindow',
			fixed: true,
			userIconClass : "w2windowContainer_nameLayer_imageIcon2",
			userIconPosition : "left"
		});
	};

	scwin.trigger2_onclick = function(e) {
	// windowContainer에  frameMode="iframe" spaReplaceHistory="false"  속성을 주고 test할 것.
		for(var i=0; i < 4; i++){
			var obj = {
				"title" : "sub"+i,
				"windowID" : "window_"+i,
				"frameMode" : "iframe",
				"src" : "windowContainer_MDI_TAB_icon_WESD-1044_(WSQ-5066)_sub"+i+".xml",
				"userIconClass" : "w2windowContainer_nameLayer_imageIcon2",
				"userIconPosition" : "left"
			};
			windowContainer1.createWindow(obj);
		}

	};

	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('windowContainer1_nameLayer_'+$p.id+'windowContainer1_subWindow0').children.length == 3;
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
